$_MODULE['<{retractationcommande}prestashop>demande_b0998d501f75050aa4045d17399c25d0'] = 'Nie można zapisać wniosku. Skontaktuj się z działem obsługi klienta.';
$_MODULE['<{retractationcommande}prestashop>demande_9914a2c75cdd71876e656e7621e47300'] = 'Twoje odstąpienie zostało zarejestrowane pod numerem %s. Potwierdzenie odbioru zostało wysłane na Twój adres e-mail. Nasz dział obsługi klienta zweryfikuje Twój wniosek i prześle Ci procedurę zwrotu.';
$_MODULE['<{retractationcommande}prestashop>demande_049d1d68c945230da39359dbd32e1d48'] = 'Twoje odstąpienie zostało zarejestrowane pod numerem %s. Potwierdzenie odbioru zostało wysłane na Twój adres e-mail. Ponieważ Twoje zamówienie zostało już wysłane, możesz odmówić przyjęcia paczki przy doręczeniu lub, jeśli ją otrzymasz, postępować zgodnie z procedurą zwrotu, którą prześle Ci nasz dział obsługi klienta.';
$_MODULE['<{retractationcommande}prestashop>demande_f49c93cbb2dab9d8c4b41d7e8a0f346d'] = 'Twoje odstąpienie zostało zarejestrowane pod numerem %s. Potwierdzenie odbioru zostało wysłane na Twój adres e-mail. Ponieważ Twoje zamówienie nie zostało jeszcze wysłane, zwrot produktu nie będzie konieczny: po weryfikacji wysyłka zostanie anulowana, a Ty otrzymasz zwrot środków.';
$_MODULE['<{retractationcommande}prestashop>demande_5a06e6b127a7d1baaf18d35bde389969'] = 'Nasz dział obsługi klienta zweryfikuje warunki Twojego wniosku (ustawowy termin 14 dni, wyłączenia z artykułu L221-28). W przypadku zgodności procedura zwrotu zostanie Ci przekazana e-mailem, a następnie zwrot nastąpi najpóźniej w ciągu 14 dni od odzyskania towaru lub otrzymania dowodu wysyłki. Prosimy nie odsyłać produktu przed otrzymaniem procedury zwrotu.';
$_MODULE['<{retractationcommande}prestashop>demande_b91f8258aeb37ba358b04427913bd6b1'] = 'Do sprawdzenia: termin 14 dni, wyłączenia ustawowe (art. L221-28), produkty już zwrócone.';
$_MODULE['<{retractationcommande}prestashop>demande_869cbd236cf583ec668d9f90469f561c'] = 'Twoje zamówienie zostało już wysłane i jest w drodze. Możesz odmówić przyjęcia paczki przy doręczeniu; jeśli ją otrzymasz, nie otwieraj jej i poczekaj na procedurę zwrotu, którą prześle Ci nasz dział obsługi klienta po weryfikacji. Zwrot nastąpi najpóźniej w ciągu 14 dni od odzyskania towaru lub otrzymania dowodu jego odesłania.';
$_MODULE['<{retractationcommande}prestashop>demande_e32237222087921238a826c436916179'] = 'ZAMÓWIENIE WYSŁANE (w drodze) — paczka została nadana: przewidzieć odmowę przyjęcia paczki lub zwrot. Do sprawdzenia: wyłączenia ustawowe (art. L221-28). Termin 14 dni rozpocznie się dopiero przy dostawie.';
$_MODULE['<{retractationcommande}prestashop>demande_ba6e3c755dec44b85c76f4e9e919450b'] = 'Ponieważ Twoje zamówienie nie zostało jeszcze wysłane, zwrot produktu nie będzie konieczny. Po weryfikacji Twojego wniosku przez nasz dział obsługi klienta wysyłka zostanie anulowana, a całość wpłaconych kwot zostanie zwrócona najpóźniej w ciągu 14 dni od Twojego wniosku tym samym sposobem płatności (art. L221-24).';
$_MODULE['<{retractationcommande}prestashop>demande_ecbc815f858a7d4a0ff0fe67f6eea2a3'] = 'ZAMÓWIENIE NIEWYSŁANE — anulowanie przed wysyłką: nie oczekuje się zwrotu produktu. Do sprawdzenia: wyłączenia ustawowe (art. L221-28). Pamiętaj o zablokowaniu wysyłki przed zatwierdzeniem.';
$_MODULE['<{retractationcommande}prestashop>demande_00e9581137cc9fcce29afdb92e74d13a'] = 'Wysłane, w drodze';
$_MODULE['<{retractationcommande}prestashop>demande_5f0d073c461f238ea2622dc70766a38f'] = 'Niewysłane w chwili złożenia wniosku';
$_MODULE['<{retractationcommande}prestashop>demande_a860874ff76e61887b36e2c13ab146f1'] = 'Potwierdzenie odbioru Twojego wniosku o odstąpienie';
$_MODULE['<{retractationcommande}prestashop>demande_cb082ed668c8c616513cef755d589f79'] = 'Nowy wniosek o odstąpienie do sprawdzenia';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_f9598f3efc5b2b93bd2643a72a431969'] = 'Mają Państwo 14 dni na odstąpienie od umowy, bez podawania przyczyny (art. L221-18 francuskiego kodeksu konsumenckiego). Termin biegnie od dnia następującego po dostawie towaru (lub po zawarciu umowy w przypadku usługi). Jeżeli upływa w sobotę, niedzielę lub dzień ustawowo wolny od pracy, ulega przedłużeniu do najbliższego dnia roboczego.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_5aea05f1d39a0423c4b25484d0bfbbfb'] = 'towary dostarczone w zapieczętowanym opakowaniu, otwarte po dostawie, których nie można zwrócić ze względu na ochronę zdrowia lub higienę;';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_44fc39e9f72aa3cbac9747645c8e3f28'] = 'treści cyfrowe dostarczane bez nośnika materialnego, których spełnianie świadczenia rozpoczęło się za Państwa zgodą;';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_b6ecb45483f4b3b9de90c6b3d7e2086c'] = 'towary, które po dostawie zostały nierozłącznie połączone z innymi rzeczami.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_ea20d48829cf42f58a7ba2e8d2ccab41'] = 'Nasz dział obsługi klienta zweryfikuje Państwa wniosek, a następnie prześle procedurę zwrotu pocztą elektroniczną. Prosimy nie odsyłać produktu lub produktów przed jej otrzymaniem oraz zwrócić towar kompletny, w stanie oryginalnym.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_c7c5d3c287928163baae28c1c94ffb57'] = 'Zamówienie już wysłane: mogą Państwo odmówić przyjęcia przesyłki przy doręczeniu. W razie jej odebrania prosimy nie otwierać paczki i postępować zgodnie z procedurą zwrotu przesłaną przez nasz dział obsługi klienta. Prosimy zwrócić towar kompletny, w stanie oryginalnym.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_ad7b6dc631e43afbd497f23ef43ab78c'] = 'Zamówienie niewysłane: zwrot produktu nie będzie konieczny. Nasz dział obsługi klienta zweryfikuje Państwa wniosek, anuluje wysyłkę i dokona zwrotu płatności.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_7d1c4561845314f94d407ede430c9a60'] = 'Jeżeli uważają Państwo, że wniosek nie został rozpatrzony zgodnie z przepisami, mogą Państwo skontaktować się z naszym działem obsługi klienta, a następnie bezpłatnie skorzystać z pomocy mediatora konsumenckiego (art. L612-1 francuskiego kodeksu konsumenckiego).';
$_MODULE['<{retractationcommande}prestashop>pdf-bon-retour_447b937c6e82f11f7c6f842ebf73a9fb'] = 'Formularz zwrotu';
