$_MODULE['<{retractationcommande}prestashop>pdf-accuse_afe72c2b21191da1897798ce03f6bb0a'] = 'Zgodnie z artykułem L221-21 francuskiego kodeksu konsumenckiego potwierdzamy otrzymanie Państwa oświadczenia o odstąpieniu od umowy';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_1d4a33337550b1d60f155dc7dca2ecef'] = 'Państwa wniosek zostanie zweryfikowany przez nasz dział obsługi klienta (dochowanie terminu ustawowego, wyłączenia przewidziane w artykule L221-28 francuskiego kodeksu konsumenckiego). W razie zgodności procedura zwrotu zostanie przesłana pocztą elektroniczną. Prosimy nie odsyłać produktu lub produktów przed jej otrzymaniem. Zwrot płatności nastąpi najpóźniej w ciągu 14 dni od odzyskania towaru lub otrzymania dowodu jego nadania, przy użyciu tego samego środka płatniczego co przy zamówieniu (art. L221-24). Bezpośrednie koszty odesłania ponoszą Państwo (art. L221-23).';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_08a4255076063ff093392602b74f2dde'] = 'Ponieważ w chwili złożenia wniosku zamówienie było już wysłane, mogą Państwo odmówić przyjęcia przesyłki przy doręczeniu albo, w razie jej odebrania, postępować zgodnie z procedurą zwrotu przesłaną przez nasz dział obsługi klienta po weryfikacji (wyłączenia przewidziane w artykule L221-28 francuskiego kodeksu konsumenckiego). Zwrot płatności nastąpi najpóźniej w ciągu 14 dni od odzyskania towaru lub otrzymania dowodu jego odesłania, przy użyciu tego samego środka płatniczego co przy zamówieniu (art. L221-24). Bezpośrednie koszty odesłania ponoszą Państwo (art. L221-23).';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_ecd429447c2c5c11827567f6c066424e'] = 'Ponieważ w chwili złożenia wniosku zamówienie nie było jeszcze wysłane, zwrot produktu nie będzie konieczny. Po weryfikacji przez nasz dział obsługi klienta (wyłączenia przewidziane w artykule L221-28 francuskiego kodeksu konsumenckiego) wysyłka zostanie anulowana, a całość wpłaconych kwot zostanie zwrócona najpóźniej w ciągu 14 dni od złożenia wniosku, przy użyciu tego samego środka płatniczego co przy zamówieniu (art. L221-24).';
$_MODULE['<{retractationcommande}prestashop>formulaire_6fd32367e8a01032b6c24770df162923'] = 'Zgodnie z artykułami L221-18 i następnymi francuskiego kodeksu konsumenckiego mają Państwo';
$_MODULE['<{retractationcommande}prestashop>formulaire_04f75f9992b78fd3affb67c8db773850'] = 'od dnia następującego po dostawie na odstąpienie od umowy, bez podawania przyczyny. Jeżeli termin ten upływa w sobotę, niedzielę lub dzień ustawowo wolny od pracy, ulega przedłużeniu do najbliższego dnia roboczego.';
$_MODULE['<{retractationcommande}prestashop>formulaire_8cac0c691d545cd91a37c8e8e044d328'] = 'Mają Państwo';
$_MODULE['<{retractationcommande}prestashop>formulaire_9f4000c0f036a4e4d1d5d03aab0c7eef'] = 'od dostawy na złożenie wniosku o zwrot.';
$_MODULE['<{retractationcommande}prestashop>formulaire_f00d6e0ec96b82767e8b675d300fd9ab'] = 'Państwa zamówienia kwalifikujące się do zwrotu';
$_MODULE['<{retractationcommande}prestashop>formulaire_7727eb7488be3ef30da590f1f667181e'] = 'Zwrot';
$_MODULE['<{retractationcommande}prestashop>formulaire_8f1d60d28b7cd074c4ed1cd8ee846423'] = 'Złóż wniosek o zwrot';
$_MODULE['<{retractationcommande}prestashop>formulaire_8e768a03b00a269f26e6cb5a6213b24f'] = 'Żadne z Państwa zamówień nie kwalifikuje się obecnie do odstąpienia od umowy (upłynął termin ustawowy lub zamówienia nie są objęte).';
$_MODULE['<{retractationcommande}prestashop>formulaire_c1ce181667f69ea149cb0a425ccdb21e'] = 'Żadne z Państwa zamówień nie kwalifikuje się obecnie do zwrotu (upłynął termin lub zamówienia nie są objęte).';
$_MODULE['<{retractationcommande}prestashop>formulaire_24eabc929ddb3eb38fd6cf81b5ffa805'] = 'Prosimy podać adres e-mail użyty przy składaniu zamówienia oraz referencję zamówienia (widoczną w e-mailu potwierdzającym).';
$_MODULE['<{retractationcommande}prestashop>formulaire_b414b1464d384d5b827c361fec76cc8f'] = 'To zamówienie nie kwalifikuje się (już) do odstąpienia online: upłynął termin ustawowy, wniosek został już złożony albo zamówienie nie jest objęte. W razie pytań prosimy o kontakt z naszym działem obsługi klienta.';
$_MODULE['<{retractationcommande}prestashop>formulaire_dbad83ecebaf719a4dd60e45bbec0e03'] = 'Prawo odstąpienia nie ma zastosowania do niektórych umów (art. L221-28 francuskiego kodeksu konsumenckiego: towary wykonane na zamówienie lub spersonalizowane, towary łatwo psujące się, towary otwarte ze względów higienicznych itp.). Po złożeniu wniosek jest weryfikowany przez nasz dział obsługi klienta, który przesyła procedurę zwrotu. Zwrot płatności następuje najpóźniej w ciągu 14 dni od odzyskania towaru lub otrzymania dowodu nadania, przy użyciu tego samego środka płatniczego. Koszty odesłania ponoszą Państwo.';
$_MODULE['<{retractationcommande}prestashop>modal_30e7d78f70861e0332aa4cbb81a2fcd3'] = 'Zwrot możliwy';
$_MODULE['<{retractationcommande}prestashop>modal_dd3b9e7bb6b5077d2235d0d84a518e91'] = 'Do wiadomości';
