$_MODULE['<{retractationcommande}prestashop>modal_217c9acbe7666448db6b898ca2ab6bef'] = 'Potwierdź wniosek o zwrot';
$_MODULE['<{retractationcommande}prestashop>modal_810a3d382ec684c35146d332e396e1c1'] = 'Po potwierdzeniu Państwa oświadczenie o odstąpieniu zostanie przekazane do naszego działu obsługi klienta, a na adres e-mail zostanie wysłane potwierdzenie odbioru wraz z egzemplarzem PDF (art. L221-21 francuskiego kodeksu konsumenckiego). Po weryfikacji przesłanek (termin ustawowy, wyłączenia z art. L221-28) otrzymają Państwo procedurę zwrotu — prosimy nie odsyłać produktów przed jej otrzymaniem. Zwrot płatności następuje najpóźniej w ciągu 14 dni od odzyskania towaru lub otrzymania dowodu nadania (wraz z kosztami dostawy w przypadku odstąpienia w całości, w pozostałych przypadkach proporcjonalnie). Koszty odesłania ponoszą Państwo.';
$_MODULE['<{retractationcommande}prestashop>modal_abeaaec30c11df72742faf07dc857200'] = 'Po potwierdzeniu Państwa oświadczenie o odstąpieniu zostanie przekazane do naszego działu obsługi klienta, a na adres e-mail zostanie wysłane potwierdzenie odbioru wraz z egzemplarzem PDF (art. L221-21 francuskiego kodeksu konsumenckiego). Ponieważ zamówienie zostało już wysłane, mogą Państwo odmówić przyjęcia przesyłki przy doręczeniu; w razie jej odebrania prosimy nie otwierać paczki i postępować zgodnie z procedurą zwrotu przesłaną przez nasz dział obsługi klienta. Zwrot płatności następuje najpóźniej w ciągu 14 dni od odzyskania towaru lub otrzymania dowodu jego odesłania. Koszty odesłania ponoszą Państwo.';
$_MODULE['<{retractationcommande}prestashop>modal_ad52dcb5592e9f635028ab04aaf1fcec'] = 'Po potwierdzeniu Państwa oświadczenie o odstąpieniu zostanie przekazane do naszego działu obsługi klienta, a na adres e-mail zostanie wysłane potwierdzenie odbioru wraz z egzemplarzem PDF (art. L221-21 francuskiego kodeksu konsumenckiego). Ponieważ zamówienie nie zostało jeszcze wysłane, zwrot produktu nie będzie konieczny: po weryfikacji (wyłączenia z art. L221-28) wysyłka zostanie anulowana, a całość wpłaconych kwot zostanie zwrócona najpóźniej w ciągu 14 dni od złożenia wniosku, przy użyciu tego samego środka płatniczego.';
$_MODULE['<{retractationcommande}prestashop>modal_c729999c38ef8dd3345cdcab0b29495a'] = 'Po potwierdzeniu Państwa wniosek o zwrot zostanie przekazany do naszego działu obsługi klienta, który zweryfikuje go zgodnie z naszymi warunkami zwrotów i przekaże dalszą procedurę. Prosimy nie odsyłać produktów przed jej otrzymaniem.';
$_MODULE['<{retractationcommande}prestashop>order-detail_5d6cad579ad55412b4c2f0e3e412a87a'] = 'Mają Państwo ustawowy termin 14 dni na odstąpienie od umowy';
$_MODULE['<{retractationcommande}prestashop>order-detail_c67d19249e1f8e4e0d574b1f5e9fd894'] = 'Mogą Państwo złożyć wniosek o zwrot w ciągu';
$_MODULE['<{retractationcommande}prestashop>order-detail_5f1fe455db6e9cab75f31be47d4a301f'] = 'dni';
$_MODULE['<{retractationcommande}prestashop>order-detail_8f1d60d28b7cd074c4ed1cd8ee846423'] = 'Złóż wniosek o zwrot';
$_MODULE['<{retractationcommande}prestashop>demande_c237e030582ecd460a9514631fa9f710'] = 'To zamówienie nie kwalifikuje się już do odstąpienia (upłynął termin ustawowy lub produkty są już objęte odstąpieniem).';
$_MODULE['<{retractationcommande}prestashop>demande_56cbaaf41017fdf11adb876a6219ba51'] = 'Nie udało się zapisać wniosku. Prosimy o kontakt z działem obsługi klienta.';
$_MODULE['<{retractationcommande}prestashop>demande_afeb49c5004af7a5c3fb574552f8524f'] = 'Państwa wniosek o zwrot został zarejestrowany pod referencją %s. Potwierdzenie zostało wysłane pocztą elektroniczną. Nasz dział obsługi klienta zweryfikuje wniosek i prześle procedurę zwrotu.';
$_MODULE['<{retractationcommande}prestashop>demande_81e83ee9703e6ffae031e8e2eded2a35'] = 'Państwa odstąpienie zostało zarejestrowane pod referencją %s. Potwierdzenie odbioru zostało wysłane pocztą elektroniczną. Ponieważ zamówienie nie zostało jeszcze wysłane, zwrot produktu nie będzie konieczny: po weryfikacji wysyłka zostanie anulowana, a płatność zwrócona.';
$_MODULE['<{retractationcommande}prestashop>demande_9f4095725b4314c97caefc7cc2bf5f14'] = 'Nasz dział obsługi klienta zweryfikuje wniosek zgodnie z naszymi warunkami zwrotów. W razie akceptacji procedura zwrotu zostanie przesłana pocztą elektroniczną. Prosimy nie odsyłać produktu przed jej otrzymaniem.';
$_MODULE['<{retractationcommande}prestashop>demande_50b76525f8ad63640702a5c148f36e5c'] = 'ZWROT HANDLOWY (zasady grupy klientów) — do weryfikacji według Państwa warunków zwrotów, a nie według prawa odstąpienia od umowy.';
$_MODULE['<{retractationcommande}prestashop>demande_1808dee14b88dac577384c0f22c5926e'] = 'Nasz dział obsługi klienta sprawdzi, czy wniosek się kwalifikuje (ustawowy termin 14 dni, wyłączenia z artykułu L221-28). W razie zgodności procedura zwrotu zostanie przesłana pocztą elektroniczną, a następnie zwrot płatności nastąpi najpóźniej w ciągu 14 dni od odzyskania towaru lub otrzymania dowodu nadania. Prosimy nie odsyłać produktu przed otrzymaniem procedury zwrotu.';
$_MODULE['<{retractationcommande}prestashop>demande_5b3514e1541cfd0318e31c694a2aa909'] = 'Państwa zamówienie zostało już wysłane i jest w drodze. Mogą Państwo odmówić przyjęcia przesyłki przy doręczeniu; w razie jej odebrania prosimy nie otwierać paczki i zaczekać na procedurę zwrotu, którą nasz dział obsługi klienta prześle po weryfikacji. Zwrot płatności nastąpi najpóźniej w ciągu 14 dni od odzyskania towaru lub otrzymania dowodu jego odesłania.';
$_MODULE['<{retractationcommande}prestashop>demande_fef84e875177fa1aa360bef363059b72'] = 'ZAMÓWIENIE WYSŁANE (w drodze) — paczka wyjechała: przewidzieć odmowę przyjęcia przesyłki lub zwrot. Do sprawdzenia: wyłączenia ustawowe (art. L221-28). Termin 14 dni zacznie biec dopiero od dostawy.';
$_MODULE['<{retractationcommande}prestashop>demande_e1a266b5d2d6ad5263f80d3a3cb670b3'] = 'Ponieważ zamówienie nie zostało jeszcze wysłane, zwrot produktu nie będzie konieczny. Po weryfikacji wniosku przez nasz dział obsługi klienta wysyłka zostanie anulowana, a całość wpłaconych kwot zostanie zwrócona najpóźniej w ciągu 14 dni od złożenia wniosku, przy użyciu tego samego środka płatniczego (art. L221-24).';
$_MODULE['<{retractationcommande}prestashop>demande_325727fe2185eac42770ba795f29f428'] = 'ZAMÓWIENIE NIEWYSŁANE — anulowanie przed wysyłką: nie należy oczekiwać zwrotu produktu. Do sprawdzenia: wyłączenia ustawowe (art. L221-28). Prosimy pamiętać o zablokowaniu wysyłki przed zatwierdzeniem.';
$_MODULE['<{retractationcommande}prestashop>demande_128b28de61f92b7372137463a6a8bbb3'] = 'Wysłane, w drodze';
